const items = ["Oksijen", "Su", "Yakıt"];
const list = document.querySelector("#list");
function render() {
  list.textContent = "";
  for (const item of items) {
    const li = document.createElement("li");
    li.textContent = item;
    list.append(li);
  }
}
render();
items.push("Kalkan");
render();

